+// failStore fails every Save while fail is set.
+type failStore struct {
+	MemStore
+	mu   sync.Mutex
+	fail bool
+}
+
+func (f *failStore) Save(s SetupState) error {
+	f.mu.Lock()
+	fail := f.fail
+	f.mu.Unlock()
+	if fail {
+		return errors.New("disk full")
+	}
+	return f.MemStore.Save(s)
+}
